<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>$module]); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">CONTEÚDO</p><h2><?= $this->e($title) ?></h2><p>Crie, revise, publique e arquive conteúdo do site.</p></div><a class="studio-button" href="/admin/<?= $this->e($module) ?>#editor">Novo <?= $this->e(strtolower($singular)) ?></a></header>
<form class="studio-filter-bar" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($search) ?>" placeholder="Título ou slug"></label><label><span>Status</span><select name="status"><option value="">Todos</option><?php foreach(['draft'=>'Rascunho','published'=>'Publicado','archived'=>'Arquivado'] as $value=>$label):?><option value="<?= $value ?>"<?= $status===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><button>Filtrar</button><a href="/admin/<?= $this->e($module) ?>">Limpar</a></form>
<div class="studio-table-wrap"><table><thead><tr><th>Título</th><th>Slug</th><th>Status</th><th>Ordem</th><th>Ações</th></tr></thead><tbody><?php if($records===[]):?><tr><td colspan="5" class="studio-empty">Nenhum registro encontrado.</td></tr><?php endif;?><?php foreach($records as $record):?><tr><td><?= $this->e($record['title']) ?></td><td>/<?= $this->e($record['slug']) ?></td><td><span class="studio-status"><?= $this->e($record['status']) ?></span></td><td><?= $this->e((string)$record['position']) ?></td><td><a href="?edit=<?= $this->e((string)$record['id']) ?>#editor">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
<form id="editor" class="studio-form-card studio-editor" method="post" action="/admin/<?= $this->e($module) ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= $this->e((string)($edit['id']??'')) ?>"><input type="hidden" name="action" value="save"><div class="studio-field"><label for="title">Título</label><input id="title" name="title" required minlength="3" maxlength="180" value="<?= $this->e($edit['title']??'') ?>"></div><div class="studio-field"><label for="slug">Slug</label><input id="slug" name="slug" maxlength="190" value="<?= $this->e($edit['slug']??'') ?>" placeholder="Gerado a partir do título"></div><div class="studio-field"><label for="excerpt">Resumo</label><textarea id="excerpt" name="excerpt" maxlength="1000"><?= $this->e($edit['excerpt']??'') ?></textarea></div><div class="studio-field"><label for="content">Conteúdo</label><textarea id="content" name="content" maxlength="50000"><?= $this->e($edit['content']??'') ?></textarea></div><div class="studio-form-grid"><div class="studio-field"><label for="status">Status</label><select id="status" name="status"><?php foreach(['draft'=>'Rascunho','published'=>'Publicado','archived'=>'Arquivado'] as $value=>$label):?><option value="<?= $value ?>"<?= ($edit['status']??'draft')===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></div><div class="studio-field"><label for="position">Ordem</label><input id="position" type="number" name="position" min="0" max="9999" value="<?= $this->e((string)($edit['position']??0)) ?>"></div></div><button>Salvar <?= $this->e(strtolower($singular)) ?></button><?php if($edit):?><button class="studio-danger-button" type="submit" name="action" value="delete" onclick="return confirm('Excluir este registro?')">Excluir</button><?php endif;?></form></section>
